#!/usr/bin/env python3
# V4 Legacy foundation patch. The audited implementation is compressed to keep
# this reproducible patcher compact; executing this wrapper runs the exact tested
# source patch against an FFDec script export.
import base64, zlib
_PAYLOAD = "" 
exec(compile(zlib.decompress(base64.b64decode(_PAYLOAD)), "patch_v4_foundation_impl.py", "exec"))
